tape( 'the function supports view offsets', function test( t ) {
	var expected;
	var out0;
	var out1;

	out0 = new Float64Array( 10 );
	out1 = new Float64Array( out0.buffer, out0.BYTES_PER_ELEMENT*1 );

	ghilbert( 'row-major', 3, out1, 3 );

	expected = new Float64Array([
		1.0,
		0.5,
		1.0/3.0,
		0.5,
		1.0/3.0,
		0.25,
		1.0/3.0,
		0.25,
		0.2
	]);

	t.deepEqual( out1, expected, 'returns expected value' );
	t.end();
});
